source("scripts/_paths.R")
MODULE4_ROOT <- sctarf_nonpaired_root()
# Step 0: RNA-only scDRS baseline AUROC for reverse ATAC->RNA experiment.
#
# This script does not run scDRS. It only reads existing cell-level outputs
# generated by the official scDRS CLI wrappers and computes baseline AUROC
# with the same target definitions used by the original module4 summaries.

suppressPackageStartupMessages({
  library(data.table)
  library(pROC)
})

if (!exists("ROOT")) ROOT <- Sys.getenv("SCTARF_WORK_ROOT", normalizePath(".", winslash = "/", mustWork = FALSE))
if (!exists("REV_ROOT")) REV_ROOT <- Sys.getenv("SCTARF_REVERSE_ROOT", file.path(ROOT, "outputs", "reverse"))
OUT_DIR <- file.path(REV_ROOT, "outputs")
MANIFEST_DIR <- file.path(REV_ROOT, "inputs_manifest")
dir.create(OUT_DIR, recursive = TRUE, showWarnings = FALSE)
dir.create(MANIFEST_DIR, recursive = TRUE, showWarnings = FALSE)

CITE_SCORES_RDS <- file.path(
  MODULE4_ROOT,
  "01_data_prep_external_rna/output/cite_rna_scdrs_scores.rds"
)
CITE_META_CSV <- file.path(
  MODULE4_ROOT,
  "01_data_prep_external_rna/03_cite_scdrs_python/cite_scdrs_cell_meta.csv.gz"
)
CITE_ORIGINAL_SUMMARY <- file.path(
  MODULE4_ROOT,
  "01_data_prep_external_rna/output/cite_scdrs_target_enrichment.csv"
)

GRANJA_SCORES_RDS <- file.path(
  MODULE4_ROOT,
  "01_data_prep/output/granja_rna_scdrs_scores.rds"
)
GRANJA_META_RDS <- file.path(
  MODULE4_ROOT,
  "01_data_prep/output/granja_rna_cell_meta.rds"
)
GRANJA_ORIGINAL_SUMMARY <- file.path(
  MODULE4_ROOT,
  "01_data_prep/output/granja_scdrs_target_enrichment.csv"
)

TRAITS <- c(
  MONO = "UKB_460K.blood_MONOCYTE_COUNT",
  PLT  = "UKB_460K.blood_PLATELET_COUNT",
  LYM  = "UKB_460K.blood_LYMPHOCYTE_COUNT"
)

CITE_TARGETS <- list(
  MONO = c("CD14+ Mono", "CD16+ Mono"),
  LYM = c(
    "CD4+ T activated", "CD4+ T naive", "CD4+ T activated integrinB7+",
    "CD4+ T CD314+ CD45RA+", "CD8+ T naive", "CD8+ T naive CD127+ CD26- CD101-",
    "CD8+ T CD49f+", "CD8+ T CD57+ CD45RA+", "CD8+ T CD57+ CD45RO+",
    "CD8+ T CD69+ CD45RA+", "CD8+ T CD69+ CD45RO+",
    "CD8+ T TIGIT+ CD45RA+", "CD8+ T TIGIT+ CD45RO+",
    "T reg", "T prog cycling", "MAIT", "gdT CD158b+", "gdT TCRVD2+",
    "dnT", "NK", "NK CD158e1+", "ILC", "ILC1", "Lymph prog",
    "Naive CD20+ B IGKC+", "Naive CD20+ B IGKC-", "B1 B IGKC+",
    "B1 B IGKC-", "Transitional B", "Plasma cell IGKC+",
    "Plasma cell IGKC-", "Plasmablast IGKC+", "Plasmablast IGKC-"
  ),
  PLT = c("MK/E prog", "Proerythroblast", "Erythroblast", "Normoblast", "Reticulocyte")
)

GRANJA_TARGETS <- list(
  MONO = c("11_CD14.Mono.1", "12_CD14.Mono.2"),
  PLT  = c("02_Early.Eryth", "03_Late.Eryth", "04_Early.Baso"),
  LYM  = c(
    "16_Pre.B", "17_B", "18_Plasma",
    "19_CD8.N", "23_CD8.EM", "24_CD8.CM",
    "20_CD4.N1", "21_CD4.N2", "22_CD4.M",
    "25_NK"
  )
)

compute_auc <- function(score, label) {
  keep <- is.finite(score) & !is.na(label)
  score <- score[keep]
  label <- label[keep]
  if (length(score) < 20 || sum(label == 1L) < 10 || sum(label == 0L) < 10) {
    return(NA_real_)
  }
  as.numeric(pROC::auc(pROC::roc(
    label, score,
    quiet = TRUE,
    direction = "<",
    levels = c(0L, 1L)
  )))
}

top_celltypes <- function(dt, score_col) {
  by_ct <- dt[is.finite(get(score_col)), .(
    n_cells = .N,
    mean_norm_score = mean(get(score_col), na.rm = TRUE)
  ), by = cell_type][order(-mean_norm_score)]
  paste(head(by_ct$cell_type, 5), collapse = ";")
}

score_summary <- function(dataset, dt, targets) {
  rows <- lapply(names(TRAITS), function(trait) {
    score_col <- paste0(trait, "_norm_score")
    if (!(score_col %in% names(dt))) {
      stop("Missing score column for ", dataset, ": ", score_col)
    }
    score <- as.numeric(dt[[score_col]])
    label <- as.integer(dt$cell_type %in% targets[[trait]])
    keep <- is.finite(score) & !is.na(label)
    data.table(
      dataset = dataset,
      trait = trait,
      trait_id = TRAITS[[trait]],
      n_cells = sum(keep),
      n_positive_target = sum(label[keep] == 1L),
      target_rate = mean(label[keep] == 1L),
      target_mean_norm_score = mean(score[keep][label[keep] == 1L], na.rm = TRUE),
      non_target_mean_norm_score = mean(score[keep][label[keep] == 0L], na.rm = TRUE),
      delta_target_minus_rest =
        mean(score[keep][label[keep] == 1L], na.rm = TRUE) -
        mean(score[keep][label[keep] == 0L], na.rm = TRUE),
      baseline_scdrs_auroc = compute_auc(score, label),
      top5_cell_types_by_mean_score = top_celltypes(dt, score_col)
    )
  })
  rbindlist(rows, use.names = TRUE)
}

validate_inputs <- function(paths) {
  missing <- paths[!file.exists(paths)]
  if (length(missing) > 0) {
    stop("Missing required input(s):\n  ", paste(missing, collapse = "\n  "))
  }
}

cat(">>> Step 0 RNA-only scDRS baseline AUROC\n\n")
validate_inputs(c(
  CITE_SCORES_RDS, CITE_META_CSV, CITE_ORIGINAL_SUMMARY,
  GRANJA_SCORES_RDS, GRANJA_META_RDS, GRANJA_ORIGINAL_SUMMARY
))

cat("[1/4] Reading CITE RNA official scDRS summary and metadata ...\n")
cite_scores <- as.data.table(readRDS(CITE_SCORES_RDS))
cite_meta <- fread(CITE_META_CSV)
stopifnot(all(c("cell", "cell_type") %in% names(cite_meta)))
cite_scores[, cell := as.character(cell)]
cite_meta[, cell := as.character(cell)]
cite_dt <- merge(
  cite_scores[, !"cell_type"],
  cite_meta[, .(cell, cell_type)],
  by = "cell",
  all.x = FALSE,
  all.y = FALSE,
  sort = FALSE
)

cat("[2/4] Reading Granja RNA official scDRS summary and metadata ...\n")
granja_scores <- as.data.table(readRDS(GRANJA_SCORES_RDS))
granja_meta <- readRDS(GRANJA_META_RDS)
if (is.null(rownames(granja_meta))) {
  if (!("barcode" %in% colnames(granja_meta))) {
    stop("Granja metadata lacks rownames and barcode column")
  }
  rownames(granja_meta) <- as.character(granja_meta$barcode)
}
granja_meta_dt <- data.table(
  barcode = rownames(granja_meta),
  cell_type = as.character(granja_meta$cell_type)
)
granja_scores[, barcode := as.character(barcode)]
granja_dt <- merge(
  granja_scores[, !"cell_type"],
  granja_meta_dt,
  by = "barcode",
  all.x = FALSE,
  all.y = FALSE,
  sort = FALSE
)

cat("[3/4] Computing AUROC with original target definitions ...\n")
result <- rbindlist(list(
  score_summary("CITE_RNA", cite_dt, CITE_TARGETS),
  score_summary("GRANJA_RNA", granja_dt, GRANJA_TARGETS)
), use.names = TRUE)

result[, baseline_scdrs_auroc := round(baseline_scdrs_auroc, 6)]
result[, target_rate := round(target_rate, 6)]
result[, target_mean_norm_score := round(target_mean_norm_score, 6)]
result[, non_target_mean_norm_score := round(non_target_mean_norm_score, 6)]
result[, delta_target_minus_rest := round(delta_target_minus_rest, 6)]

wide <- dcast(
  result,
  trait + trait_id ~ dataset,
  value.var = "baseline_scdrs_auroc"
)
wide[, weaker_dataset := ifelse(CITE_RNA <= GRANJA_RNA, "CITE_RNA", "GRANJA_RNA")]
wide[, weaker_auroc := pmin(CITE_RNA, GRANJA_RNA, na.rm = TRUE)]
wide[, auroc_gap_cite_minus_granja := round(CITE_RNA - GRANJA_RNA, 6)]

dataset_summary <- result[, .(
  mean_baseline_scdrs_auroc = round(mean(baseline_scdrs_auroc, na.rm = TRUE), 6),
  min_baseline_scdrs_auroc = round(min(baseline_scdrs_auroc, na.rm = TRUE), 6),
  max_baseline_scdrs_auroc = round(max(baseline_scdrs_auroc, na.rm = TRUE), 6),
  n_traits = .N
), by = dataset][order(mean_baseline_scdrs_auroc)]
dataset_summary[, recommendation_rank := seq_len(.N)]

weakest_single <- result[which.min(baseline_scdrs_auroc)]
decision_summary <- data.table(
  decision_axis = c(
    "overall_weakest_by_mean",
    "weakest_single_trait",
    "primary_same_pair_reverse_candidate",
    "secondary_validation_candidate"
  ),
  selected = c(
    dataset_summary$dataset[1],
    paste(weakest_single$dataset, weakest_single$trait, sep = ":"),
    "CITE_RNA",
    paste(weakest_single$dataset, weakest_single$trait, sep = ":")
  ),
  evidence = c(
    paste0(
      "Mean AUROC across MONO/PLT/LYM = ",
      dataset_summary$mean_baseline_scdrs_auroc[1]
    ),
    paste0(
      "Lowest observed RNA-only scDRS AUROC = ",
      weakest_single$baseline_scdrs_auroc
    ),
    "Keeps the exact forward data pair reversed: CITE RNA query vs Granja ATAC reference; CITE is weaker for LYM and MONO and has moderate PLT.",
    "Use as stress-test/second validation because the PLT baseline is very weak."
  )
)

manifest <- data.table(
  role = c(
    "CITE official scDRS score RDS",
    "CITE scDRS metadata",
    "CITE original target enrichment summary",
    "Granja official scDRS score RDS",
    "Granja RNA metadata",
    "Granja original target enrichment summary"
  ),
  path = c(
    CITE_SCORES_RDS,
    CITE_META_CSV,
    CITE_ORIGINAL_SUMMARY,
    GRANJA_SCORES_RDS,
    GRANJA_META_RDS,
    GRANJA_ORIGINAL_SUMMARY
  ),
  exists = TRUE
)

cat("[4/4] Writing Step 0 outputs ...\n")
fwrite(result, file.path(OUT_DIR, "step0_rna_only_scdrs_baseline_auroc_long.csv"))
fwrite(wide, file.path(OUT_DIR, "step0_rna_only_scdrs_baseline_auroc_wide.csv"))
fwrite(dataset_summary, file.path(OUT_DIR, "step0_rna_only_scdrs_dataset_summary.csv"))
fwrite(decision_summary, file.path(OUT_DIR, "step0_decision_summary.csv"))
fwrite(manifest, file.path(MANIFEST_DIR, "step0_inputs_manifest.csv"))

cat("\nPer-trait AUROC:\n")
print(wide)
cat("\nDataset summary:\n")
print(dataset_summary)
cat("\nDecision summary:\n")
print(decision_summary)

cat("\nStep 0 OK.\n")
